<script setup lang="ts">
import { onMounted,ref } from 'vue';import {supabase} from '@/lib/supabase'
const loading=ref(true),error=ref(''),stats=ref({sales:0,revenue:0,products:0,lowStock:0,credits:0,expenses:0}),recent=ref<any[]>([])
onMounted(async()=>{try{const [s,p,c,e,r]=await Promise.all([supabase.from('sales').select('grand_total,created_at').gte('created_at',new Date(new Date().setHours(0,0,0,0)).toISOString()),supabase.from('products').select('id,stock,track_inventory'),supabase.from('credits').select('balance').eq('status','open'),supabase.from('expenses').select('amount').gte('date',new Date().toISOString().slice(0,10)),supabase.from('sales').select('id,receipt_no,grand_total,payment_method,created_at').order('created_at',{ascending:false}).limit(8)]);for(const x of [s,p,c,e,r])if(x.error)throw x.error;stats.value={sales:s.data.length,revenue:s.data.reduce((a,x)=>a+Number(x.grand_total||0),0),products:p.data.length,lowStock:p.data.filter(x=>x.track_inventory&&x.stock<=5).length,credits:c.data.reduce((a,x)=>a+Number(x.balance||0),0),expenses:e.data.reduce((a,x)=>a+Number(x.amount||0),0)};recent.value=r.data}catch(x:any){error.value=x.message??'Dashboard unavailable'}finally{loading.value=false}})
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>Dashboard</h1><p>Business overview · {{new Date().toLocaleDateString()}}</p></div></div><p v-if="error" class="alert">{{error}}</p><div v-if="loading" class="empty">Loading dashboard…</div><template v-else><div class="stats-grid"><article class="stat"><span>Today's sales</span><strong>{{stats.sales}}</strong></article><article class="stat"><span>Today's revenue</span><strong>UGX {{stats.revenue.toLocaleString()}}</strong></article><article class="stat"><span>Products</span><strong>{{stats.products}}</strong></article><article class="stat"><span>Low stock (≤5)</span><strong>{{stats.lowStock}}</strong></article><article class="stat"><span>Customer credit outstanding</span><strong>UGX {{stats.credits.toLocaleString()}}</strong></article><article class="stat"><span>Today's expenses</span><strong>UGX {{stats.expenses.toLocaleString()}}</strong></article></div><div class="panel mt"><h2>Recent sales</h2><div class="table-scroll"><table><thead><tr><th>Receipt</th><th>Date</th><th>Payment</th><th>Total</th></tr></thead><tbody><tr v-for="s in recent" :key="s.id"><td>{{s.receipt_no??s.id}}</td><td>{{new Date(s.created_at).toLocaleString()}}</td><td>{{s.payment_method}}</td><td>UGX {{Number(s.grand_total).toLocaleString()}}</td></tr><tr v-if="!recent.length"><td colspan="4" class="empty">No sales recorded yet.</td></tr></tbody></table></div></div></template></section></template>
